// Select invoice attachments and hand each one to LP-MCP as base64 JSON.
//
// Thin transport, no logic (handoff 2026-10-12 §7.1): one item per attachment
// of a kind the ledger reads (pdf / png / jpg / jpeg / tif / tiff / heic / csv
// / xlsx). An email with NO such attachment still produces one item carrying
// the plain-text body (some vendors bill in the email body). LP-MCP dedupes on
// the file's sha256, so a re-poll of the same message is a harmless duplicate.
//
// The Gmail trigger is scoped by `to:` so it never sees LP report mail or
// anything else on the shared mailbox. Do not remove that scoping.
const KEEP = /\.(pdf|png|jpe?g|tiff?|heic|csv|xlsx)$/i;
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const headers = j.headers || {};
  const from = j.from?.value?.[0]?.address || j.from?.text || headers.from || j.From || '';
  const subject = j.subject || headers.subject || j.Subject || '';
  const received_at = j.date || headers.date || j.internalDate || null;
  const gmail_message_id = j.id || j.messageId || headers['message-id'] || null;
  const body_text = j.text || j.textPlain || (typeof j.html === 'string' ? j.html.replace(/<[^>]+>/g, ' ') : '') || '';
  const bin = items[i].binary ?? {};
  let emitted = 0;
  for (const key of Object.keys(bin)) {
    const fileName = bin[key]?.fileName ?? '';
    if (!KEEP.test(fileName)) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    out.push({ json: {
      gmail_message_id, from, subject, received_at,
      file_name: fileName, mime_type: bin[key]?.mimeType || null,
      file_b64: buf.toString('base64'),
    } });
    emitted++;
  }
  if (!emitted && String(body_text).trim()) {
    out.push({ json: { gmail_message_id, from, subject, received_at, file_name: null, mime_type: 'text/plain', file_b64: null, body_text: String(body_text).slice(0, 200000) } });
  }
}
return out;
